/* ****************************************************************************
-- Source file: la_top_s9.v
-- Description: Top level for the Bitmain Antminer S9 control board
--              ( "AntMiner ControlBoard XC7010", XC7Z010-1CLG400 ).
--
--   The S9 board has no oscillator on the PL side ( Y2/Y3 are not fitted ),
--   so the 100 MHz clock comes from the PS: FCLK_CLK0 of processing_system7.
--   The PS block design "la_ps" is generated by vivado/build.tcl.
--   FCLK0 only runs after the PS was initialized by a boot loader
--   ( e.g. Linux booted from the microSD card sets FCLK0 = 100 MHz ).
--
--   Pins ( hash-board connectors J1..J9, all 3.3 V, bank 34 ):
--     J1 pin 11 = bd_tx  -> RXD of the USB-UART adapter
--     J1 pin 12 = bd_rx  <- TXD of the USB-UART adapter
--     J5..J8 pins 5,11,12,15 = probe D0..D15
--     J9 pin 5 = tp_sel_n : leave open = probes, short to GND = test pattern
--     4 on-board LEDs D5..D8 ( active low )
--
-- Language:    Verilog-2001
-- ***************************************************************************/
`timescale 1 ns/ 100 ps
`default_nettype none

module la_top_s9
(
  // PS7 dedicated pins ( DDR and MIO ), required by processing_system7
  inout  wire [14:0]  DDR_addr,
  inout  wire [2:0]   DDR_ba,
  inout  wire         DDR_cas_n,
  inout  wire         DDR_ck_n,
  inout  wire         DDR_ck_p,
  inout  wire         DDR_cke,
  inout  wire         DDR_cs_n,
  inout  wire [3:0]   DDR_dm,
  inout  wire [31:0]  DDR_dq,
  inout  wire [3:0]   DDR_dqs_n,
  inout  wire [3:0]   DDR_dqs_p,
  inout  wire         DDR_odt,
  inout  wire         DDR_ras_n,
  inout  wire         DDR_reset_n,
  inout  wire         DDR_we_n,
  inout  wire         FIXED_IO_ddr_vrn,
  inout  wire         FIXED_IO_ddr_vrp,
  inout  wire [53:0]  FIXED_IO_mio,
  inout  wire         FIXED_IO_ps_clk,
  inout  wire         FIXED_IO_ps_porb,
  inout  wire         FIXED_IO_ps_srstb,

  // PL pins
  input  wire [15:0]  probe,
  input  wire         tp_sel_n,
  input  wire         bd_rx,
  output wire         bd_tx,
  output wire [3:0]   led_n
);// module la_top_s9

  wire          fclk0;
  wire          fclk0_reset_n;
  wire [3:0]    led;


//-----------------------------------------------------------------------------
// Zynq PS : only used as the PL clock source
//-----------------------------------------------------------------------------
la_ps_wrapper u_la_ps
(
  .DDR_addr          ( DDR_addr          ),
  .DDR_ba            ( DDR_ba            ),
  .DDR_cas_n         ( DDR_cas_n         ),
  .DDR_ck_n          ( DDR_ck_n          ),
  .DDR_ck_p          ( DDR_ck_p          ),
  .DDR_cke           ( DDR_cke           ),
  .DDR_cs_n          ( DDR_cs_n          ),
  .DDR_dm            ( DDR_dm            ),
  .DDR_dq            ( DDR_dq            ),
  .DDR_dqs_n         ( DDR_dqs_n         ),
  .DDR_dqs_p         ( DDR_dqs_p         ),
  .DDR_odt           ( DDR_odt           ),
  .DDR_ras_n         ( DDR_ras_n         ),
  .DDR_reset_n       ( DDR_reset_n       ),
  .DDR_we_n          ( DDR_we_n          ),
  .FIXED_IO_ddr_vrn  ( FIXED_IO_ddr_vrn  ),
  .FIXED_IO_ddr_vrp  ( FIXED_IO_ddr_vrp  ),
  .FIXED_IO_mio      ( FIXED_IO_mio      ),
  .FIXED_IO_ps_clk   ( FIXED_IO_ps_clk   ),
  .FIXED_IO_ps_porb  ( FIXED_IO_ps_porb  ),
  .FIXED_IO_ps_srstb ( FIXED_IO_ps_srstb ),
  .FCLK_CLK0         ( fclk0             ),
  .FCLK_RESET0_N     ( fclk0_reset_n     )
);// u_la_ps


//-----------------------------------------------------------------------------
// Logic analyzer. No PL buttons on this board, test pattern via J9 jumper.
//-----------------------------------------------------------------------------
la_core u_la_core
(
  .clk_100m     ( fclk0                ),
  .clk_locked   ( 1'b1                 ),// Own power-on reset in la_core
  .btn          ( 4'b0000              ),
  .sw           ( { 1'b0, ~tp_sel_n }  ),
  .probe        ( probe[15:0]          ),
  .bd_rx        ( bd_rx                ),
  .bd_tx        ( bd_tx                ),
  .led          ( led[3:0]             )
);// u_la_core

  assign led_n = ~led;


endmodule // la_top_s9.v
`default_nettype wire
